        code_s13_config: '<code><span class="c">#:schema https://developers.openai.com/codex/config-schema.json</span>\n<span class="c"># ~/.codex/config.toml — permission profile path</span>\nmodel = "gpt-5.6-sol"\nreview_model = "gpt-5.6-terra"\nmodel_reasoning_effort = "medium"\nplan_mode_reasoning_effort = "medium"\napproval_policy = "on-request"\napprovals_reviewer = "user"\ndefault_permissions = "project_safe"\nweb_search = "cached"\npersonality = "friendly"\n\n<span class="c"># Do not combine this with sandbox_mode or sandbox_workspace_write</span>\n[permissions.project_safe]\ndescription = "Read and write only inside the current project"\nextends = ":workspace"\n\n[permissions.project_safe.network]\nenabled = false\n\n[features]\nfast_mode = true\n\n[tools]\nweb_search = { context_size = "medium", allowed_domains = ["learn.chatgpt.com", "developers.openai.com", "openai.com"] }\nview_image = true\n\n<span class="c"># OpenAI Docs MCP</span>\n[mcp_servers.openaiDeveloperDocs]\nurl = "https://developers.openai.com/mcp"\nrequired = true</code>',
